let arraycsv = msg.payload; //cargamos todo el contenido que viene del nodo csv
let nmro_registros = arraycsv.length;//obtenemos el largo del array (cant.elementos)

msg.index = nmro_registros;

flow.set("potencia_max", msg.payload[0].potencia);

for (let i = 0; i < nmro_registros; i++) {
    if (flow.get("potencia_max") < msg.payload[i].potencia) {
        flow.set("potencia_max", msg.payload[i].potencia);
    }
}

msg.payload = flow.get("potencia_max");
return msg;

let arraycsv = msg.payload;
let nmro_registros = arraycsv.length;

let suma_corriente = 0;

for (let i = 0; i < nmro_registros; i++) {
    suma_corriente += msg.payload[i].corriente;
}


flow.set("corriente_promedio", suma_corriente / nmro_registros);

msg.payload = flow.get("corriente_promedio");

return msg;

let RPM = flow.get("RPM");

if (RPM != undefined){
    msg.payload = RPM;
    return msg;
}

let correo_agregar = flow.get("correo_escrito");

if (correo_agregar != undefined && correo_agregar != "") {

    if (flow.get("array_correos") == undefined) {

        let arr_correos = [];
        arr_correos.push(correo_agregar);
        flow.set("array_correos", arr_correos);

    }
    else {

        let arr_correos = flow.get("array_correos");
        arr_correos.push(correo_agregar);
        flow.set("array_correos", arr_correos);

    }

    msg.options = flow.get("array_correos");
    msg.payload = "";
    flow.set("correo_escrito", "");

    return msg;
}

let correo_eliminar = flow.get("correo_escrito");

if(correo_eliminar != undefined || correo_eliminar != ""){

    if(flow.get("array_correos") != undefined){

        let array = flow.get("array_correos");

        if(array.includes(correo_eliminar)){

            let indice = array.indexOf(correo_eliminar);
            array.splice(indice, 1);
            flow.set("array_correos", array);

        }

        msg.options = flow.get("array_correos");
        msg.payload = "";
        flow.set("correo_escrito", "");
        return msg;
    }
}

function randomTen() {
    const min = 218;
    const max = 222;
    const v = Math.random() * (max - min) + min;
    return parseFloat(v.toFixed(1));
}

msg.payload = randomTen();
flow.set("Tension", msg.payload);
return msg;

function randomCor() {
    const min = 40;
    const max = 50;
    const v = Math.random() * (max - min) + min;
    return parseFloat(v.toFixed(1));
}

msg.payload = randomCor();
flow.set("Corriente", msg.payload);
return msg;

let potencia
potencia = (flow.get("Tension") * flow.get("Corriente")/1000).toFixed(2)
msg.payload = potencia;
return msg;

